import { useState, useMemo, useCallback, memo } from 'react';

// Child only re-renders if its props change
const ExpensiveChild = memo(function ExpensiveChild({ onClick }) {
  console.log('Child rendered');
  return <button onClick={onClick}>Click Child</button>;
});

function Parent() {
  const [count, setCount] = useState(0);
  const [name, setName] = useState('');

  // Only recalculates when count changes
  const doubled = useMemo(() => {
    console.log('Computing doubled...');
    return count * 2;
  }, [count]);

  // Same function reference between renders unless count changes
  const handleClick = useCallback(() => {
    console.log('Count is:', count);
  }, [count]);

  return (
    <div>
      <input value={name} onChange={e => setName(e.target.value)} placeholder="Type name..." />
      <p>Count: {count} | Doubled: {doubled}</p>
      <button onClick={() => setCount(c => c + 1)}>Increment</button>
      <ExpensiveChild onClick={handleClick} />
    </div>
  );
}
